def parse_dockerfile(path):
    lines = open(path, encoding="utf-8").read().splitlines()
    joined = []
    buf = ""
    for raw in lines:
        s = raw.rstrip()
        stripped = s.strip()
        if not stripped or stripped.startswith("#"):
            if not buf:
                continue
        if s.endswith("\\"):
            buf += s[:-1] + " "
            continue
        buf += s
        if buf.strip():
            joined.append(buf.strip())
        buf = ""
    if buf.strip():
        joined.append(buf.strip())
    out = []
    for line in joined:
        if line.startswith("#"):
            continue
        parts = line.split(None, 1)
        if not parts:
            continue
        instr = parts[0].upper()
        args = parts[1] if len(parts) > 1 else ""
        out.append((instr, args))
    return out

instrs = parse_dockerfile('Dockerfile')
seq = [(i, a) for i, a in instrs]

# find the package.json COPY, the npm install RUN, and the full 'COPY . .'
pkg_copy = full_copy = install = None
for idx, (instr, args) in enumerate(seq):
    if instr == 'COPY':
        srcs = args.split()[:-1]
        if any('package' in s for s in srcs):
            if pkg_copy is None:
                pkg_copy = idx
        if srcs == ['.']:
            full_copy = idx
    if instr == 'RUN' and 'npm install' in args:
        install = idx

assert pkg_copy is not None, 'must COPY the package manifest before installing'
assert install is not None, 'npm install RUN missing'
assert full_copy is not None, 'must still COPY the rest of the source'
assert pkg_copy < install < full_copy, \
    f'order must be: copy manifest ({pkg_copy}) -> npm install ({install}) -> copy source ({full_copy})'
print('PASS')
